SELECT COUNT(1) AS order_count, SUM(CASE WHEN risk_status = 1 THEN 1 ELSE 0 END) AS risk_order_count, IFNULL(SUM(pay_amount), 0) AS pay_amount, IFNULL(SUM(refund_amount), 0) AS refund_amount, IFNULL(SUM(net_pay_amount), 0) AS net_pay_amount, IFNULL(SUM(product_cost), 0) AS product_cost, IFNULL(SUM(bonus_amount), 0) AS bonus_amount, IFNULL(SUM(company_share_amount), 0) AS company_share_amount, IFNULL(SUM(company_profit), 0) AS company_profit FROM dms_order_finance WHERE 1 = 1
AND create_time >= #{startTime}
AND create_time < #{endTime}

SELECT DATE(create_time) AS stat_date, COUNT(1) AS order_count, SUM(CASE WHEN risk_status = 1 THEN 1 ELSE 0 END) AS risk_order_count, IFNULL(SUM(pay_amount), 0) AS pay_amount, IFNULL(SUM(refund_amount), 0) AS refund_amount, IFNULL(SUM(net_pay_amount), 0) AS net_pay_amount, IFNULL(SUM(product_cost), 0) AS product_cost, IFNULL(SUM(bonus_amount), 0) AS bonus_amount, IFNULL(SUM(company_share_amount), 0) AS company_share_amount, IFNULL(SUM(company_profit), 0) AS company_profit FROM dms_order_finance WHERE 1 = 1
AND create_time >= #{startTime}
AND create_time < #{endTime}
GROUP BY DATE(create_time) ORDER BY stat_date ASC
